@push('styles')
<style>
#kt_app_toolbar{display:none!important}
.role-report-dashboard{--accent:#2563eb;--accent-dark:#1e3a8a;--accent-soft:#eff6ff;--hero-end:#dbeafe;--ink:#111d3b;--muted:#667085;color:var(--ink);font:12px Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;padding:0 8px 22px}.role-report-dashboard[data-report-theme="warehouse"]{--accent:#f59e0b;--accent-dark:#123a5a;--accent-soft:#fff7e6;--hero-end:#cfeaf7}.role-report-dashboard[data-report-theme="owner"]{--accent:#d4a72c;--accent-dark:#172554;--accent-soft:#fffbeb;--hero-end:#dbeafe}.role-report-dashboard[data-report-theme="users"]{--accent:#7c3aed;--accent-dark:#4c1d95;--accent-soft:#f5f3ff;--hero-end:#ede9fe}.role-report-dashboard[data-report-theme="system"]{--accent:#06b6d4;--accent-dark:#111827;--accent-soft:#ecfeff;--hero-end:#c7d2fe}.role-report-dashboard *{box-sizing:border-box}.role-report-header{min-height:77px;display:flex;align-items:center;justify-content:space-between;gap:18px}.role-report-heading{display:flex;align-items:center;gap:13px;min-width:0}.role-report-icon{width:42px;height:42px;border-radius:11px;background:var(--accent-soft);color:var(--accent);display:flex;align-items:center;justify-content:center;flex:0 0 42px}.role-report-icon i{font-size:23px}.role-report-eyebrow{font-size:9px;font-weight:800;letter-spacing:.12em;color:var(--accent);text-transform:uppercase}.role-report-heading h1{font-size:23px;line-height:1.15;margin:2px 0}.role-report-heading p{margin:0;color:var(--muted)}.role-report-actions{display:flex;align-items:center;gap:9px}.role-report-period,.role-report-action{height:39px;border:1px solid #e4e8ef;border-radius:9px;background:#fff;display:inline-flex;align-items:center;gap:8px;padding:0 12px;color:var(--ink);box-shadow:0 3px 10px rgba(15,23,42,.04)}.role-report-action{width:40px;justify-content:center;padding:0;text-decoration:none}.role-report-filter{border:1px solid #e4e8ef;border-radius:12px;background:#fff;padding:13px 15px;margin-bottom:18px;box-shadow:0 3px 12px rgba(15,23,42,.04)}.role-report-filter .report-profile-filter{margin:0}.role-report-summary{display:grid;grid-template-columns:minmax(210px,250px) minmax(0,1fr);gap:16px;align-items:center;min-height:130px;padding:14px 17px;border:1px solid color-mix(in srgb,var(--accent) 20%,white);border-radius:13px;background:linear-gradient(110deg,var(--accent-soft),#fff 56%,var(--hero-end));margin-bottom:17px;overflow:hidden}.role-report-summary-copy h2{font-size:19px;margin:0 0 6px}.role-report-summary-copy p{margin:0;color:var(--muted);line-height:1.45}.role-report-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));background:rgba(255,255,255,.78);border-radius:13px;padding:13px 2px}.role-report-kpi{padding:0 16px;border-right:1px solid #e5e9ef;min-width:0}.role-report-kpi:last-child{border:0}.role-report-kpi span,.role-report-kpi small{display:block;color:var(--muted)}.role-report-kpi span{font-size:10px;font-weight:650;margin-bottom:8px}.role-report-kpi strong{display:block;font-size:20px;line-height:1.15;white-space:normal;overflow-wrap:anywhere;margin-bottom:6px}.role-report-kpi small{font-size:9px}.role-report-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.role-report-panel{border:1px solid #e4e8ef;border-radius:13px;background:#fff;min-width:0;min-height:285px;padding:15px;box-shadow:0 4px 13px rgba(15,23,42,.045)}.role-report-panel-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:15px}.role-report-panel-heading h2{font-size:16px;margin:0}.role-report-panel-heading p{font-size:10px;color:var(--muted);margin:3px 0 0}.role-report-panel-heading a{font-size:10px;font-weight:700;color:#1676df;text-decoration:underline;white-space:nowrap}.role-report-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin-bottom:14px}.role-report-metrics>div{padding:2px 10px;border-right:1px solid #e5e9ef;min-width:0}.role-report-metrics>div:first-child{padding-left:0}.role-report-metrics>div:last-child{border:0}.role-report-metrics span{display:block;font-size:9px;color:var(--muted);margin-bottom:5px}.role-report-metrics strong{font-size:16px;overflow-wrap:anywhere}.role-report-table-wrap{overflow:hidden}.role-report-panel table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:9.5px}.role-report-panel th{background:#f3f5f9;color:#59647b;text-align:left}.role-report-panel th,.role-report-panel td{padding:7px 6px;border-bottom:1px solid #eaedf2;white-space:normal;overflow-wrap:anywhere;vertical-align:top}.role-report-bars{display:grid;gap:13px}.role-bar-row{position:relative}.role-bar-row>div:first-child{display:flex;justify-content:space-between;gap:10px;margin-bottom:5px}.role-bar-row span{color:#4d5870}.role-bar-track{height:10px;background:#edf1f5;border-radius:10px;overflow:hidden}.role-bar-track i{display:block;height:100%;border-radius:10px;background:linear-gradient(90deg,var(--accent-dark),var(--accent));transition:filter .18s ease,transform .18s ease}.role-bar-row:hover .role-bar-track i{filter:brightness(1.18);transform:scaleY(1.25)}.role-report-empty{height:175px;display:flex;align-items:center;justify-content:center;color:#8a94a7}.role-report-links{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:15px}.role-report-links a{display:flex;justify-content:space-between;align-items:center;gap:8px;border:1px solid #e4e8ef;border-radius:10px;background:#fff;padding:11px 13px;color:var(--ink);font-weight:650;text-decoration:none}.role-report-links a:hover{border-color:var(--accent);background:var(--accent-soft);color:var(--accent-dark)}
@media(max-width:1199px){.role-report-grid{grid-template-columns:1fr 1fr}.role-report-panel:last-child{grid-column:1/-1}.role-report-links{grid-template-columns:repeat(3,1fr)}}
@media(max-width:767px){.role-report-dashboard{padding:0 3px 18px}.role-report-header{display:block;padding:7px 3px 14px}.role-report-actions{margin-top:12px}.role-report-period{flex:1}.role-report-summary{display:block}.role-report-summary-copy{margin-bottom:12px}.role-report-kpis{grid-template-columns:1fr 1fr}.role-report-kpi{padding:10px;border-bottom:1px solid #e5e9ef}.role-report-grid{grid-template-columns:1fr}.role-report-panel:last-child{grid-column:auto}.role-report-links{grid-template-columns:1fr 1fr}.role-report-filter{overflow:hidden}}
</style>
@endpush
